import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, AmbientLight, DirectionalLight, Color } from 'three/webgpu';
import { mix, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();

  // ---------- Backdrop ----------
  const gradientNode = mix(
    vec3(new Color('#0b0b10')),
    vec3(new Color('#13131a')),
    uv().y
  );
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradientNode;
  const backdrop = new Mesh(new PlaneGeometry(7, 5.5), backdropMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);

  // ---------- Lights ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(5, 5, 5);
  const rim = new DirectionalLight(0xffffff, 0.8);
  rim.position.set(-5, -5, -5);
  root.add(ambient, key, rim);

  // ---------- Text Content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Helper to create text mesh
  const makeText = (content, opts) => ctx.fontAtlas.createText(content, opts);

  // ----- Hero (kinetic) -----
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  root.add(heroGroup);

  const heroItem = items.find(i => i.role === 'hero') || { text: 'TIME, MACHINED.' };
  const heroWords = heroItem.text.split(' ');
  const heroOffsets = [0.12, 0.0, -0.12];
  let heroX = 0;
  heroWords.forEach((w, i) => {
    const txt = makeText(w, {
      fontSize: 124,
      color: '#16161d',
      align: 'center',
    });
    txt.position.set(heroX, 0, heroOffsets[i] ?? 0);
    // rough spacing estimate
    heroX += w.length * 0.06;
    heroGroup.add(txt);
  });

  // ----- Underline -----
  const underlineGeom = new PlaneGeometry(2.6, 0.045);
  const underlineMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.2,
    metalness: 0,
    roughness: 0.5,
  });
  const underline = new Mesh(underlineGeom, underlineMat);
  underline.position.set(-1.3, -0.05, 0); // left‑anchored
  underline.scale.set(0, 1, 1);
  root.add(underline);

  // ----- Subhead -----
  const subItem = items.find(i => i.role === 'subhead') || { text: 'Every calibre begins as a solid billet.' };
  const subText = makeText(subItem.text, {
    fontSize: 40,
    color: '#16161d',
    align: 'center',
  });
  subText.position.set(0, -0.65, 0);
  root.add(subText);

  // ----- Caption -----
  const capItem = items.find(i => i.role === 'caption') || { text: 'NOVA ATELIER / CALIBRE PROGRAM' };
  const capText = makeText(capItem.text, {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.12 * 18, // approx em to px
  });
  capText.position.set(0, 1.15, 0);
  root.add(capText);

  // ---------- Cinematic Primitive ----------
  const primitivesList = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach(p => {
      const prim = ctx.primitives[p.name](root, p.params);
      primitivesList.push(prim);
    });
  }

  // ---------- GSAP Timelines ----------
  const timelines = [];

  // Underline reveal after kinetic text
  const glyphDuration = 0.7; // 700 ms
  const stagger = 0.06; // 60 ms
  const underlineDelay = glyphDuration + (heroWords.length - 1) * stagger + 0.12;
  const underlineTL = gsap.timeline();
  underlineTL.to(underline.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.out',
    delay: underlineDelay,
  });
  timelines.push(underlineTL);

  // Weighted‑settle after last glyph (handled by primitive, but ensure final scale)
  const settleTL = gsap.timeline();
  settleTL.to(heroGroup.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.9,
    ease: 'power4.out',
    delay: underlineDelay + 0.5,
    onComplete: () => {
      gsap.to(heroGroup.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power4.out' });
    },
  });
  timelines.push(settleTL);

  // ---------- UserData ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // dispose geometries & materials
    backdrop.geometry.dispose();
    backdropMat.dispose();

    underline.geometry.dispose();
    underlineMat.dispose();

    // dispose any textures that may have been loaded (none in this node)

    // cleanup primitives
    primitivesList.forEach(p => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });

    // kill GSAP timelines
    timelines.forEach(tl => tl.kill());

    // dispose text objects
    root.traverse(child => {
      if (child.isMesh && child.geometry && child.geometry.dispose) child.geometry.dispose();
      if (child.material && child.material.dispose) child.material.dispose();
    });
  };

  return root;
}
